// Build the customer message (spec §7). Input is the event envelope:
// { event, ticket_id, data: <ticket>, notify_template }.
// Enforces exactly-once per (ticket_id, event) via the ticket's notified_events (§7.5).
const env = $input.first().json;
const ticket = env.data || {};
const tpl = env.notify_template;
const eventName = env.event;

// No template for this boundary (e.g. Triage) → nothing to send (§7.1).
if (!tpl) return [{ json: { __skip: true, reason: 'no-template' } }];
// Idempotency guard: already notified for this event → skip (§7.5).
if ((ticket.notified_events || []).includes(eventName))
  return [{ json: { __skip: true, reason: 'already-notified' } }];

const locale = $env.FSC_LOCALE || 'es';
const base = $env.FSC_BASE_URL || '';
const statusLink = `${base}/intake/index.html?id=${encodeURIComponent(ticket.ticket_id)}&t=${encodeURIComponent(ticket.access_token)}`;
const etaLocal = ticket.eta ? new Date(ticket.eta).toLocaleString(locale === 'es' ? 'es-ES' : 'en-GB') : '';

const T = {
  es: {
    T1: `Hola ${ticket.customer_name}, recibimos tu solicitud de servicio para ${ticket.equipment_type}. Tu número de ticket es ${ticket.ticket_id}. Te avisaremos cuando asignemos un técnico. Seguimiento: ${statusLink}`,
    T2: `${ticket.customer_name}, asignamos a ${ticket.assigned_technician} a tu ticket ${ticket.ticket_id}. Pronto te confirmaremos la hora estimada de llegada.`,
    T3: `${ticket.assigned_technician} va en camino para tu ticket ${ticket.ticket_id}. Hora estimada de llegada: ${etaLocal}.`,
    T4: `${ticket.assigned_technician} ha llegado para atender tu ticket ${ticket.ticket_id}.`,
    T5: `Tu servicio ${ticket.ticket_id} se ha completado. Gracias por confiar en nosotros. Si el problema persiste, responde a este mensaje.`
  },
  en: {
    T1: `Hi ${ticket.customer_name}, we received your service request for ${ticket.equipment_type}. Your ticket is ${ticket.ticket_id}. We'll let you know when a technician is assigned. Track it: ${statusLink}`,
    T2: `${ticket.customer_name}, we assigned ${ticket.assigned_technician} to your ticket ${ticket.ticket_id}. We'll confirm the ETA shortly.`,
    T3: `${ticket.assigned_technician} is on the way for your ticket ${ticket.ticket_id}. ETA: ${etaLocal}.`,
    T4: `${ticket.assigned_technician} has arrived to handle your ticket ${ticket.ticket_id}.`,
    T5: `Your service ${ticket.ticket_id} is complete. Thank you. If the issue persists, reply to this message.`
  }
};
const body = (T[locale] || T.es)[tpl];
return [{ json: { __skip: false, ticket_id: ticket.ticket_id, event: eventName, to: ticket.customer_phone, body, provider: $env.FSC_NOTIFY_PROVIDER || 'whatsapp_cloud', from: $env.FSC_NOTIFY_FROM } }];

// Record outcome on the ticket: append event to notified_events + set notification_status.
// 'failed' is surfaced in the supervisor view as a dead-letter flag (§7.5, §8.4).
const msg = $('Build message').first().json;
let sent = false;
try {
  const node = $('WhatsApp sent?');
  sent = true; // reached the success branch
} catch (e) { sent = false; }
return [{ json: {
  ticket_id: msg.ticket_id,
  event: msg.event,
  notification_status: sent ? 'sent' : 'failed'
} }];
